import { expect, expectStatus, test } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

test.describe("review vendors", () => {
  test(
    "submitting a draft vendor with all documents extracted moves it to in_review and records an audit event",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a draft vendor with a unique name.
      const member = await apiAs("member");
      const suffix = uniqueSuffix();
      const created = await expectStatus<{ id: string; status: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `REV-01 Vendor ${suffix}`,
            category: "services",
            contact_email: `rev01-${suffix}@example.test`,
          },
        }),
        201,
      );
      expect(created.status).toBe("draft");
      const vendorId = created.id;

      // Arrange: upload one document of each kind and wait for extraction to finish.
      for (const kind of KINDS) {
        const uploaded = await expectStatus<{ id: string }>(
          await member.post(`/api/vendors/${vendorId}/documents`, {
            multipart: {
              kind,
              file: {
                name: `${kind}-${suffix}.pdf`,
                mimeType: "application/pdf",
                buffer: Buffer.from("%PDF-1.4 REV-01 test document"),
              },
            },
          }),
          201,
        );

        await expect
          .poll(
            async () =>
              (await expectStatus<{ status: string }>(await member.get(`/api/documents/${uploaded.id}`), 200)).status,
            { timeout: 60_000, message: `document ${kind} should reach extracted` },
          )
          .toBe("extracted");
      }

      // Act: submit the vendor for review.
      const submitted = await expectStatus<{ id: string; status: string }>(
        await member.post(`/api/vendors/${vendorId}/submit`),
        200,
      );

      // Assert: the vendor is now in review.
      expect(submitted.id).toBe(vendorId);
      expect(submitted.status).toBe("in_review");

      // Assert: the audit trail records the submission.
      const trail = await expectStatus<{ items: { action: string }[] }>(
        await member.get(`/api/vendors/${vendorId}/audit`),
        200,
      );
      const actions = trail.items.map((event) => event.action);
      expect(actions).toContain("vendor.submitted");
    },
  );
});
